use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let s = input.as_str().unwrap();
    let mut result = String::new();
    for c in s.chars() {
        if c.is_alphabetic() {
            let base = if c.is_uppercase() { 65 } else { 97 };
            let offset = if c.is_uppercase() { 32 } else { 97 };
            let new_char = (c as u8 - base + offset) % 26 + base;
            result.push((new_char as char).to_string());
        } else {
            result.push(c);
        }
    }
    Value::String(result)
}
